#include "app.h"
#include "video_sw.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
/* Preprocessed native GX RGBA8 tiles. No PNG decoding, no network calls or
 * large allocations on every rendered frame. Generated by cover_sync.py. */
#define COV_W 128
#define COV_H 160
#define COV_BYTES (COV_W*COV_H*4)
typedef struct { char key[120]; void *pixels; int valid; int system; unsigned last; } Cache;
static Cache cache[12];static unsigned clock_id=0;
static void key_for(const Game*g,char*key,size_t cap){
 if(g->id[0]){snprintf(key,cap,"%s",g->id);return;}
 size_t n=0;for(const char*p=g->name;*p&&n+1<cap;p++){
  unsigned char c=(unsigned char)*p;if(c>='a'&&c<='z')c-=32;
  if((c>='A'&&c<='Z')||(c>='0'&&c<='9'))key[n++]=c;
  else if(c==' '&&n&&key[n-1]!='-')key[n++]='-';
 }key[n]=0;
}
static Cache*lookup(const Game*g){
 char key[120];key_for(g,key,sizeof(key));if(!*key)return NULL;
 clock_id++;
 for(int j=0;j<12;j++)if(cache[j].key[0]&&cache[j].system==(int)g->system&&!strcmp(cache[j].key,key)){
  cache[j].last=clock_id;return cache[j].valid?&cache[j]:NULL;
 }
 int slot=-1;for(int j=0;j<12;j++)if(!cache[j].key[0]){slot=j;break;}
 if(slot<0){slot=0;for(int j=1;j<12;j++)if(cache[j].last<cache[slot].last)slot=j;}
 Cache*c=&cache[slot];
 /* CPU rendering completes before this cache entry is recycled. */
 free(c->pixels);
 memset(c,0,sizeof(*c));
 snprintf(c->key,sizeof(c->key),"%s",key);c->system=(int)g->system;c->last=clock_id;
 char p[200];FILE*f=NULL;
 for(int root=0;root<2;root++){
  snprintf(p,sizeof(p),"%s:/maizo/covers/%s.gxt",root?"sd":"usb",key);
  f=fopen(p,"rb");if(f)break;
 }
 if(!f)return NULL;
 unsigned char hdr[8];
 if(fread(hdr,1,8,f)!=8||memcmp(hdr,"MZG1",4)||hdr[4]!=0||hdr[5]!=COV_W||hdr[6]!=0||hdr[7]!=COV_H){fclose(f);return NULL;}
 c->pixels=malloc(COV_BYTES);if(!c->pixels){fclose(f);return NULL;}
 if(fread(c->pixels,1,COV_BYTES,f)!=COV_BYTES){free(c->pixels);c->pixels=NULL;fclose(f);return NULL;}
 fclose(f);
 c->valid=1;return c;
}
int cover_draw(const Game*g,float x,float y,float w,float h){
 Cache*c=lookup(g);
 if(!c)return 0;
 maizo_video_cover((const unsigned char*)c->pixels,x,y,w,h);
 return 1;
}
